-- c007-v002: dan aku–melihat lain malaikat, naik dari terbit matahari, mempunyai meterai Allah yang–hidup; dan dia–berseru suara keras kepada– empat malaikat kepada–siapa diberikan kepada–mereka merusakkan – bumi dan – laut,
-- c007-v003: berkata, Jangan rusakkan – bumi, atau – laut, atau – pohon-pohon, sampai kami–memeteraikan – hamba-hamba – Allah kita, di–atas – dahi mereka.
-- c007-v004: Dan aku–mendengar – jumlah – yang–dimeteraikan, seratus empat–puluh empat ribu, dimeteraikan dari setiap suku anak-anak Israel;
