-- c007-v006: dari suku Asyer, dua–belas ribu; dari suku Naftali, dua–belas ribu; dari suku Manasye, dua–belas ribu;
-- c007-v007: dari suku Simeon, dua–belas ribu; dari suku Lewi, dua–belas ribu; dari suku Isakhar, dua–belas ribu;
-- c007-v008: dari suku Zebulon, dua–belas ribu; dari suku Yusuf, dua–belas ribu; dari suku Benyamin, dua–belas ribu dimeteraikan.
-- c007-v009: Setelah ini aku–melihat, dan lihatlah, orang–banyak besar, yang menghitung itu tidak–seorangpun dapat; dari setiap bangsa, dan suku, dan kaum, dan bahasa, berdiri di–hadapan – takhta dan di–hadapan – Anak–Domba, berpakaian jubah putih, dan daun–palem di – tangan mereka;
-- c007-v010: dan mereka–berseru suara keras, berkata, – Keselamatan kepada– Allah kita, kepada–yang duduk di–atas – takhta, dan kepada– Anak–Domba!
-- c007-v011: dan semua – malaikat berdiri sekeliling – takhta, dan – tua-tua, dan – empat makhluk–hidup, dan tersungkur di–hadapan – takhta atas – wajah mereka, dan menyembah – Allah,
-- c007-v012: berkata, Amin! – berkat, dan – kemuliaan, dan – hikmat, dan – ucapan–syukur, dan – hormat, dan – kuasa, dan – kekuatan, kepada– Allah kita, sampai – selama-lamanya – selama-lamanya! Amin.
-- c007-v013: Dan menjawab satu dari – tua-tua, berkata kepadaku, Ini –yang berpakaian – jubah – putih, siapa mereka–adalah, dan dari–mana mereka–datang?
-- c007-v014: dan aku–berkata kepadanya, Tuanku, aku, engkau tahu. dan dia–berkata kepadaku, Ini adalah –yang datang dari – penderitaan – besar, dan mereka–mencuci – jubah mereka, dan memutihkan itu dalam – darah – Anak–Domba.
-- c007-v015: Karena–itu, itu, mereka–ada di–hadapan – takhta – Allah, dan mereka–melayani Dia siang dan malam di – bait–suci –Nya; dan –yang duduk di–atas – takhta akan–menaungi atas mereka.
